import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
  inOutEnvelope,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 10;

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ──────────────────────────────────────────────────────────────
// SCENE 1 — Hero headline with orange-highlighted phrase
// ──────────────────────────────────────────────────────────────
const sceneOneDuration = 75;

const SceneHero: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const envelope = inOutEnvelope(frame, vfps, sceneOneDuration);

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const highlightIn = springIn(frame, vfps, 22, "LIQUID");
  const tailIn = springIn(frame, vfps, 18, "SNAPPY");
  const subIn = springIn(frame, vfps, 36, "GENTLE");

  const driftY = ambientDrift(frame, 2.5, 110, "hero-headline");
  const eyebrowDrift = ambientDrift(frame, 1.5, 130, "eyebrow");

  const LEAD = "Actors";
  const TAIL = "— built for agents.";

  return (
    <AbsoluteFill style={{ background: COLORS.bg, opacity: envelope }}>
      <Background />

      {/* Eyebrow — top-left */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "16%",
          fontFamily: "monospace",
          fontSize: base * 0.018,
          color: COLORS.textSubtle,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [12, 0]) + eyebrowDrift}px)`,
        }}
      >
        01 / new release
      </div>

      {/* Headline column — centered narrow column, anchored slightly left */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          right: "9%",
          top: "32%",
          transform: `translateY(${driftY}px)`,
        }}
      >
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: base * 0.115,
            color: COLORS.text,
            letterSpacing: "-0.035em",
            lineHeight: 1.02,
          }}
        >
          {/* "Actors" lead — letter-by-letter SNAPPY reveal */}
          <span style={{ display: "inline-flex" }}>
            {LEAD.split("").map((ch, i) => {
              const charIn = springIn(frame, vfps, 6 + i * 2, "SNAPPY");
              const ty = interpolate(charIn, [0, 1], [48, 0]);
              const sc = interpolate(charIn, [0, 1], [0.92, 1]);
              const bl = interpolate(charIn, [0, 1], [8, 0]);
              return (
                <span
                  key={i}
                  style={{
                    display: "inline-block",
                    opacity: charIn,
                    transform: `translateY(${ty}px) scale(${sc})`,
                    filter: `blur(${bl}px)`,
                    whiteSpace: "pre",
                  }}
                >
                  {ch}
                </span>
              );
            })}
          </span>{" "}
          {/* Highlighted phrase pill — draws in left-to-right */}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(2, base * 0.0035)}px solid ${COLORS.orange}`,
              padding: `0 ${base * 0.014}px`,
              borderRadius: base * 0.008,
              color: COLORS.text,
              display: "inline-block",
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            built for agents
          </span>
          <span
            style={{
              display: "inline-block",
              opacity: tailIn,
              transform: `translateY(${interpolate(tailIn, [0, 1], [20, 0])}px)`,
              marginLeft: base * 0.012,
            }}
          >
            .
          </span>
        </div>

        {/* Subhead */}
        <div
          style={{
            marginTop: base * 0.035,
            fontFamily: BRAND.fonts.primary,
            fontWeight: 400,
            fontSize: base * 0.024,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.4,
            maxWidth: width * 0.55,
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [14, 0])}px)`,
          }}
        >
          Programmable cloud workers. One primitive, infinite outputs.
        </div>
      </div>

      {/* Counter caption — bottom-right */}
      <div
        style={{
          position: "absolute",
          right: "9%",
          bottom: "13%",
          fontFamily: "monospace",
          fontSize: base * 0.017,
          color: COLORS.textSubtle,
          letterSpacing: "0.18em",
          opacity: eyebrowIn,
        }}
      >
        v1 / shipping now
      </div>
    </AbsoluteFill>
  );
};

// ──────────────────────────────────────────────────────────────
// SCENE 2 — 3-node flow diagram: Trigger → Actor → Output
// ──────────────────────────────────────────────────────────────
const sceneTwoDuration = 90;

const NODES = [
  {
    label: "Trigger",
    descriptor: "Webhook, schedule, API",
    glyph: "⚡",
  },
  {
    label: "Actor",
    descriptor: "Your serverless worker",
    glyph: "◆",
    emphasis: true,
  },
  {
    label: "Output",
    descriptor: "Dataset, KV, stream",
    glyph: "→",
  },
];

const FlowNode: React.FC<{
  node: (typeof NODES)[number];
  index: number;
  delay: number;
  total: number;
  centerY: number;
  nodeSize: number;
  base: number;
}> = ({ node, delay, base, nodeSize }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const nodeIn = springIn(frame, vfps, delay, "ELASTIC");
  const labelIn = springIn(frame, vfps, delay + 6, "GENTLE");
  const breathe = ambientDrift(frame, 1.5, 90, `node-${node.label}`);
  const pulse = ambientDrift(frame, 0.015, 75, `pulse-${node.label}`);

  const sc = interpolate(nodeIn, [0, 1], [0.4, 1]);
  const ty = interpolate(nodeIn, [0, 1], [16, 0]);

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: base * 0.018,
      }}
    >
      {/* Circular node */}
      <div
        style={{
          width: nodeSize,
          height: nodeSize,
          borderRadius: "50%",
          background: node.emphasis ? COLORS.orangeTint : "rgba(255,255,255,0.04)",
          border: `${Math.max(1.5, base * 0.002)}px solid ${
            node.emphasis ? COLORS.orange : COLORS.border
          }`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: BRAND.fonts.marketing,
          fontWeight: 600,
          fontSize: nodeSize * 0.36,
          color: node.emphasis ? COLORS.orange : COLORS.text,
          opacity: nodeIn,
          transform: `translateY(${ty + breathe}px) scale(${sc + pulse})`,
          boxShadow: node.emphasis
            ? `0 0 ${nodeSize * 0.4}px ${COLORS.orangeTint}`
            : "none",
        }}
      >
        {node.glyph}
      </div>

      {/* Label below */}
      <div
        style={{
          opacity: labelIn,
          transform: `translateY(${interpolate(labelIn, [0, 1], [10, 0])}px)`,
          textAlign: "center",
        }}
      >
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: base * 0.03,
            color: COLORS.text,
            letterSpacing: "-0.01em",
            lineHeight: 1.1,
          }}
        >
          {node.label}
        </div>
        <div
          style={{
            marginTop: base * 0.008,
            fontFamily: BRAND.fonts.primary,
            fontWeight: 400,
            fontSize: base * 0.016,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
          }}
        >
          {node.descriptor}
        </div>
      </div>
    </div>
  );
};

const SceneFlow: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const envelope = inOutEnvelope(frame, vfps, sceneTwoDuration);

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const titleIn = springIn(frame, vfps, 8, "SNAPPY");

  // Connecting line: draws left to right after first node arrives
  const lineProgress1 = springIn(frame, vfps, 26, "LIQUID");
  const lineProgress2 = springIn(frame, vfps, 42, "LIQUID");

  const driftY = ambientDrift(frame, 2, 120, "flow-headline");

  const nodeSize = base * 0.11;
  const centerY = height * 0.55;
  const colGap = width * 0.18;

  return (
    <AbsoluteFill style={{ background: COLORS.bg, opacity: envelope }}>
      <Background />

      {/* Eyebrow */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "14%",
          fontFamily: "monospace",
          fontSize: base * 0.018,
          color: COLORS.textSubtle,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [10, 0])}px)`,
        }}
      >
        How it works
      </div>

      {/* Section headline */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          right: "9%",
          top: "20%",
          transform: `translateY(${driftY}px)`,
        }}
      >
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: base * 0.055,
            color: COLORS.text,
            letterSpacing: "-0.025em",
            lineHeight: 1.1,
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [18, 0])}px)`,
            maxWidth: width * 0.55,
          }}
        >
          From{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(2, base * 0.003)}px solid ${COLORS.orange}`,
              padding: `0 ${base * 0.01}px`,
              borderRadius: base * 0.006,
            }}
          >
            signal
          </span>{" "}
          to result in three steps.
        </div>
      </div>

      {/* Flow diagram — horizontal row, centered */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: centerY - nodeSize * 0.5 - base * 0.04,
          display: "flex",
          justifyContent: "center",
          alignItems: "flex-start",
          gap: colGap - nodeSize,
        }}
      >
        {NODES.map((node, i) => (
          <FlowNode
            key={node.label}
            node={node}
            index={i}
            delay={14 + i * 12}
            total={NODES.length}
            centerY={centerY}
            nodeSize={nodeSize}
            base={base}
          />
        ))}
      </div>

      {/* Connecting lines drawn via SVG */}
      <svg
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
        }}
      >
        {/* Line 1: Trigger → Actor */}
        {(() => {
          const cx = width / 2;
          const halfGap = colGap / 2;
          const startX = cx - halfGap + nodeSize * 0.55;
          const endX = cx - nodeSize * 0.55;
          const y = centerY;
          const totalLen = endX - startX;
          const currentEnd = startX + totalLen * lineProgress1;
          const arrowOp = interpolate(lineProgress1, [0.85, 1], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          return (
            <>
              <line
                x1={startX}
                y1={y}
                x2={currentEnd}
                y2={y}
                stroke={COLORS.orange}
                strokeWidth={Math.max(1.5, base * 0.002)}
                strokeLinecap="round"
              />
              {/* Arrow head */}
              <polygon
                points={`${endX},${y} ${endX - base * 0.012},${y - base * 0.007} ${endX - base * 0.012},${y + base * 0.007}`}
                fill={COLORS.orange}
                opacity={arrowOp}
              />
            </>
          );
        })()}
        {/* Line 2: Actor → Output */}
        {(() => {
          const cx = width / 2;
          const halfGap = colGap / 2;
          const startX = cx + nodeSize * 0.55;
          const endX = cx + halfGap - nodeSize * 0.55;
          const y = centerY;
          const totalLen = endX - startX;
          const currentEnd = startX + totalLen * lineProgress2;
          const arrowOp = interpolate(lineProgress2, [0.85, 1], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          return (
            <>
              <line
                x1={startX}
                y1={y}
                x2={currentEnd}
                y2={y}
                stroke={COLORS.orange}
                strokeWidth={Math.max(1.5, base * 0.002)}
                strokeLinecap="round"
              />
              <polygon
                points={`${endX},${y} ${endX - base * 0.012},${y - base * 0.007} ${endX - base * 0.012},${y + base * 0.007}`}
                fill={COLORS.orange}
                opacity={arrowOp}
              />
            </>
          );
        })()}
      </svg>

      {/* Footer caption */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          bottom: "10%",
          fontFamily: "monospace",
          fontSize: base * 0.016,
          color: COLORS.textSubtle,
          letterSpacing: "0.18em",
          textTransform: "uppercase",
          opacity: interpolate(frame, [50, 65], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }),
        }}
      >
        apify.com/actors
      </div>
    </AbsoluteFill>
  );
};

// ──────────────────────────────────────────────────────────────
// SCENE 3 — Tagline close: "Build. Run. Scale."
// Extended by 125 frames (5s @ 25fps) to linger on the final composition.
// ──────────────────────────────────────────────────────────────
const sceneThreeDuration = 55 + 125;

const SceneTagline: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  // Custom envelope — fade IN as before, but DO NOT fade out (final scene of video).
  const fadeIn = interpolate(frame, [0, 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const envelope = fadeIn;

  const words = ["Build.", "Run.", "Scale."];

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const ctaIn = springIn(frame, vfps, 28, "LIQUID");

  const driftY = ambientDrift(frame, 2, 100, "tagline");
  const ctaPulse = ambientDrift(frame, 0.008, 60, "cta-pulse");
  // Extra ambient breath on the held tagline so the 5s linger never feels frozen.
  const taglineBreath = ambientDrift(frame, 1.2, 140, "tagline-breath");

  return (
    <AbsoluteFill style={{ background: COLORS.bg, opacity: envelope }}>
      <Background />

      {/* Eyebrow top-left */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "16%",
          fontFamily: "monospace",
          fontSize: base * 0.018,
          color: COLORS.textSubtle,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [10, 0])}px)`,
        }}
      >
        Get started
      </div>

      {/* Tagline — left anchored, big, word-by-word */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          right: "9%",
          top: "34%",
          transform: `translateY(${driftY + taglineBreath}px)`,
          fontFamily: BRAND.fonts.marketing,
          fontWeight: 600,
          fontSize: base * 0.14,
          color: COLORS.text,
          letterSpacing: "-0.04em",
          lineHeight: 0.95,
          display: "flex",
          flexWrap: "wrap",
          gap: base * 0.035,
        }}
      >
        {words.map((w, i) => {
          const wordIn = springIn(frame, vfps, 6 + i * 8, "SNAPPY");
          const ty = interpolate(wordIn, [0, 1], [40, 0]);
          const sc = interpolate(wordIn, [0, 1], [0.92, 1]);
          const bl = interpolate(wordIn, [0, 1], [10, 0]);
          // Per-word residual drift so each word breathes at its own rate during the linger.
          const wordDrift = ambientDrift(frame, 0.9, 100 + i * 13, `word-${i}`);
          // Highlight the middle word
          const isHighlight = i === 1;
          return (
            <span
              key={w}
              style={{
                display: "inline-block",
                opacity: wordIn,
                transform: `translateY(${ty + wordDrift}px) scale(${sc})`,
                filter: `blur(${bl}px)`,
                color: isHighlight ? COLORS.orange : COLORS.text,
              }}
            >
              {w}
            </span>
          );
        })}
      </div>

      {/* CTA outlined pill */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          bottom: "20%",
          opacity: ctaIn,
          transform: `translateY(${interpolate(ctaIn, [0, 1], [14, 0])}px) scale(${1 + ctaPulse})`,
        }}
      >
        <div
          style={{
            display: "inline-block",
            border: `${Math.max(1.5, base * 0.002)}px solid ${COLORS.orange}`,
            borderRadius: 999,
            padding: `${base * 0.014}px ${base * 0.028}px`,
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: base * 0.022,
            color: COLORS.orange,
            letterSpacing: "-0.005em",
          }}
        >
          Try Apify free →
        </div>
      </div>

      {/* Promo line below CTA */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          bottom: "13%",
          fontFamily: BRAND.fonts.primary,
          fontWeight: 400,
          fontSize: base * 0.016,
          color: COLORS.textMuted,
          letterSpacing: "-0.003em",
          opacity: ctaIn,
        }}
      >
        $5 free credit · No card required
      </div>

      {/* Corner caption */}
      <div
        style={{
          position: "absolute",
          right: "9%",
          bottom: "13%",
          fontFamily: "monospace",
          fontSize: base * 0.016,
          color: COLORS.textSubtle,
          letterSpacing: "0.18em",
          opacity: ctaIn,
        }}
      >
        apify.com
      </div>
    </AbsoluteFill>
  );
};

// ──────────────────────────────────────────────────────────────
// Main composition
// ──────────────────────────────────────────────────────────────
export const durationInFrames =
  sceneOneDuration + sceneTwoDuration + sceneThreeDuration - TRANSITION * 2;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={sceneOneDuration + TRANSITION}>
        <SceneHero />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />
      <TransitionSeries.Sequence durationInFrames={sceneTwoDuration + TRANSITION}>
        <SceneFlow />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />
      <TransitionSeries.Sequence durationInFrames={sceneThreeDuration}>
        <SceneTagline />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
